    ///
    /// e - disable multi-line matching
    ///
    /// i - case-insensitive
    ///
    /// m - multi-line matching
    ///
    /// s - make `.` match newlines
    ///
    /// w - match full words only
    #[arg(short = 'f', long = "flags", value_name = "FLAGS")]
    flags: Option<String>,
}

fn build_regex(find: &str, fixed_strings: bool, flags: &Option<String>) -> Result<Regex> {
    let pattern = if fixed_strings {
        regex::escape(find)
    } else {
        find.to_string()
    };

    // Wrap in word boundary if 'w' flag is set
    let flags_str = flags.as_deref().unwrap_or("");
    let use_word_boundary = flags_str.contains('w');
    let pattern = if use_word_boundary {
        format!(r"\b{}\b", pattern)
    } else {
        pattern
    };

    let mut builder = RegexBuilder::new(&pattern);

    // Default: multiline is enabled
    // 'e' flag disables multiline
    // 'm' flag enables multiline
    // Default behavior: multi_line = true (anchors ^ and $ match line boundaries)
    let mut multi_line = true;
    let mut case_insensitive = false;
    let mut dot_matches_newline = false;

    for ch in flags_str.chars() {
        match ch {
            'i' => case_insensitive = true,
            'c' => case_insensitive = false,
            'm' => multi_line = true,
            'e' => multi_line = false,
            's' => dot_matches_newline = true,
            'w' => {} // handled above
            _ => {}
        }
    }

    builder.multi_line(multi_line);
    builder.case_insensitive(case_insensitive);
    builder.dot_matches_new_line(dot_matches_newline);

    Ok(builder.build().with_context(|| format!("Invalid regex: {}", pattern))?)
}

