    // Handle $$ -> $ escaping and process replacements
    if max_replacements == 0 {
        // Unlimited replacements
        perform_replacement(content, regex, replacement, None)
    } else {
        perform_replacement(content, regex, replacement, Some(max_replacements))
    }
}

fn perform_replacement(content: &str, regex: &Regex, replacement: &str, limit: Option<usize>) -> String {
    // We need to handle $$ -> $ after replacement
    // The replacement string uses $1, $2, ${name} syntax
    // We need to convert our replacement format to what regex crate expects
    // The regex crate uses $1, $2, ${name} as well, so that's compatible
    // But we need to handle $$ -> $ escaping

