    // $$ -> a placeholder, then after regex replacement, convert placeholder back to $
    // Actually, let's handle it differently:
    // We need to escape $$ to avoid it being treated as a capture group reference

    // Strategy: convert $$ to a unique placeholder before regex replacement,
    // then convert the placeholder back to $ after

    // In regex crate, $$ is not a valid escape - we need to handle it manually

    let count = limit.unwrap_or(usize::MAX);
    let mut result = String::new();
    let mut last_end = 0;
    let mut replacements_done = 0;

    for cap in regex.captures_iter(content) {
        if replacements_done >= count {
            break;
        }
        let m = cap.get(0).unwrap();
        result.push_str(&content[last_end..m.start()]);

        // Perform the replacement with capture group substitution
        let replaced = substitute_captures(&cap, replacement);
        result.push_str(&replaced);

        last_end = m.end();
        replacements_done += 1;
    }

    result.push_str(&content[last_end..]);
    result
}

fn substitute_captures(caps: &regex::Captures, replacement: &str) -> String {
    let mut result = String::new();
    let chars: Vec<char> = replacement.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        if chars[i] == '$' {
            if i + 1 < chars.len() {
                if chars[i + 1] == '$' {
                    // $$ -> $
                    result.push('$');
                    i += 2;
                } else if chars[i + 1] == '{' {
                    // ${name} or ${N}
                    if let Some(end) = replacement[i+2..].find('}') {
                        let name = &replacement[i+2..i+2+end];
                        i += 2 + end + 1; // skip past closing }

                        // Try numeric first
                        if let Ok(n) = name.parse::<usize>() {
                            if let Some(m) = caps.get(n) {
                                result.push_str(m.as_str());
                            }
                        } else {
                            // Named capture
                            if let Some(m) = caps.name(name) {
                                result.push_str(m.as_str());
                            }
                        }
                    } else {
                        result.push('$');
                        i += 1;
                    }
                } else if chars[i + 1].is_ascii_digit() {
                    // $N or $NN - collect all consecutive digits
                    let mut j = i + 1;
                    while j < chars.len() && chars[j].is_ascii_digit() {
                        j += 1;
                    }
                    let num_str: String = chars[i+1..j].iter().collect();
                    let n: usize = num_str.parse().unwrap();
                    if let Some(m) = caps.get(n) {
                        result.push_str(m.as_str());
                    }
                    i = j;
                } else if chars[i + 1].is_alphabetic() || chars[i + 1] == '_' {
                    // $name - collect identifier chars
                    let mut j = i + 1;
                    while j < chars.len() && (chars[j].is_alphanumeric() || chars[j] == '_') {
                        j += 1;
                    }
                    let name: String = chars[i+1..j].iter().collect();
                    // Try named capture
                    if let Some(m) = caps.name(&name) {
                        result.push_str(m.as_str());
                        i = j;
                    } else {
                        // No such named capture - output nothing (empty replacement)
                        i = j;
                    }
                } else {
                    result.push('$');
                    i += 1;
                }
            } else {
                result.push('$');
                i += 1;
            }
        } else {
            result.push(chars[i]);
            i += 1;
        }
    }

    result
}

fn process_content(content: &str, regex: &Regex, replacement: &str, max_replacements: usize) -> String {
    replace_all(content, regex, replacement, max_replacements)
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    let regex = build_regex(&cli.find, cli.fixed_strings, &cli.flags)?;

    if cli.files.is_empty() {
        // Read from stdin
        let mut input = String::new();
        io::stdin().read_to_string(&mut input)
            .context("Failed to read from stdin")?;

        let output = process_content(&input, &regex, &cli.replace_with, cli.max_replacements);

        let stdout = io::stdout();
        let mut handle = stdout.lock();
        handle.write_all(output.as_bytes())
            .context("Failed to write to stdout")?;
    } else if cli.files.len() == 1 && !cli.preview {
        // Single file, no preview - modify in place
        let path = &cli.files[0];
        let content = fs::read_to_string(path)
            .with_context(|| format!("Failed to read file: {}", path.display()))?;

        let output = process_content(&content, &regex, &cli.replace_with, cli.max_replacements);

        fs::write(path, output.as_bytes())
            .with_context(|| format!("Failed to write file: {}", path.display()))?;
    } else if cli.preview {
        if cli.files.is_empty() {
            // Already handled above
        } else if cli.files.len() == 1 {
            // Single file preview - just output to stdout
            let path = &cli.files[0];
            let content = fs::read_to_string(path)
                .with_context(|| format!("Failed to read file: {}", path.display()))?;

            let output = process_content(&content, &regex, &cli.replace_with, cli.max_replacements);

            let stdout = io::stdout();
            let mut handle = stdout.lock();
            handle.write_all(output.as_bytes())
                .context("Failed to write to stdout")?;
        } else {
            // Multiple files preview - show file headers
            let stdout = io::stdout();
            let mut handle = stdout.lock();

            for path in &cli.files {
                let content = fs::read_to_string(path)
                    .with_context(|| format!("Failed to read file: {}", path.display()))?;

                let output = process_content(&content, &regex, &cli.replace_with, cli.max_replacements);

                writeln!(handle, "----- FILE {} -----", path.display())
                    .context("Failed to write to stdout")?;
                handle.write_all(output.as_bytes())
                    .context("Failed to write to stdout")?;
            }
        }
    } else {
        // Multiple files, no preview - modify each in place
        for path in &cli.files {
            let content = fs::read_to_string(path)
                .with_context(|| format!("Failed to read file: {}", path.display()))?;

            let output = process_content(&content, &regex, &cli.replace_with, cli.max_replacements);

            fs::write(path, output.as_bytes())
                .with_context(|| format!("Failed to write file: {}", path.display()))?;
        }
    }

    Ok(())
}
