	preview         bool
	fixedStrings    bool
	maxReplacements int
	flags           string
	flagsSet        bool
}

func parseArgs(args []string) (*Config, error) {
	cfg := &Config{}
	positional := []string{}
	endOfFlags := false
	flagsSetCount := 0

	i := 0
	for i < len(args) {
		arg := args[i]

		if endOfFlags {
			positional = append(positional, arg)
			i++
			continue
		}

		if arg == "--" {
			endOfFlags = true
			i++
			continue
		}

		if strings.HasPrefix(arg, "-") && arg != "-" {
			switch arg {
			case "-p", "--preview":
				cfg.preview = true
				i++
			case "-F", "--fixed-strings":
				cfg.fixedStrings = true
				i++
			case "-h", "--help":
				printHelp(true)
				os.Exit(0)
			case "-V", "--version":
				fmt.Printf("sd %s\n", version)
				os.Exit(0)
			case "-n", "--max-replacements":
				if i+1 >= len(args) {
					return nil, fmt.Errorf("missing argument for %s", arg)
				}
				n, err := strconv.Atoi(args[i+1])
				if err != nil {
					return nil, fmt.Errorf("invalid number: %s", args[i+1])
				}
				cfg.maxReplacements = n
				i += 2
			case "-f", "--flags":
				if flagsSetCount > 0 {
					return nil, fmt.Errorf("the argument '--flags <FLAGS>' cannot be used multiple times")
				}
				if i+1 >= len(args) {
					return nil, fmt.Errorf("missing argument for %s", arg)
				}
				cfg.flags = args[i+1]
				cfg.flagsSet = true
				flagsSetCount++
				i += 2
			default:
				// Check if it's a short flag with value like -n5
				if strings.HasPrefix(arg, "-n") && len(arg) > 2 {
					n, err := strconv.Atoi(arg[2:])
					if err != nil {
						return nil, fmt.Errorf("unexpected argument '%s'", arg)
					}
					cfg.maxReplacements = n
					i++
				} else if strings.HasPrefix(arg, "-f") && len(arg) > 2 {
					cfg.flags = arg[2:]
					cfg.flagsSet = true
					flagsSetCount++
					i++
				} else if strings.HasPrefix(arg, "--max-replacements=") {
					val := arg[len("--max-replacements="):]
					n, err := strconv.Atoi(val)
					if err != nil {
						return nil, fmt.Errorf("invalid number: %s", val)
					}
					cfg.maxReplacements = n
					i++
				} else if strings.HasPrefix(arg, "--flags=") {
					if flagsSetCount > 0 {
						return nil, fmt.Errorf("the argument '--flags <FLAGS>' cannot be used multiple times")
					}
					cfg.flags = arg[len("--flags="):]
					cfg.flagsSet = true
					flagsSetCount++
					i++
