func substituteCaptures(submatches []string, subexpNames []string, replacement string) string {
	var result strings.Builder
	runes := []rune(replacement)
	i := 0

	for i < len(runes) {
		if runes[i] == '$' {
			if i+1 < len(runes) {
				if runes[i+1] == '$' {
					result.WriteRune('$')
					i += 2
				} else if runes[i+1] == '{' {
					// ${name} or ${N}
					rest := string(runes[i+2:])
					end := strings.Index(rest, "}")
					if end >= 0 {
						name := rest[:end]
						i += 2 + end + 1

						// Try numeric
						if n, err := strconv.Atoi(name); err == nil {
							if n < len(submatches) {
								result.WriteString(submatches[n])
							}
						} else {
							// Named capture
							for idx, capName := range subexpNames {
								if capName == name && idx < len(submatches) {
									result.WriteString(submatches[idx])
									break
								}
							}
						}
					} else {
						result.WriteRune('$')
						i++
					}
				} else if unicode.IsDigit(runes[i+1]) {
					// $N or $NN...
					j := i + 1
					for j < len(runes) && unicode.IsDigit(runes[j]) {
						j++
					}
					numStr := string(runes[i+1 : j])
					n, _ := strconv.Atoi(numStr)
					if n < len(submatches) {
						result.WriteString(submatches[n])
					}
					i = j
				} else if unicode.IsLetter(runes[i+1]) || runes[i+1] == '_' {
					// $name
					j := i + 1
					for j < len(runes) && (unicode.IsLetter(runes[j]) || unicode.IsDigit(runes[j]) || runes[j] == '_') {
						j++
					}
					name := string(runes[i+1 : j])
					for idx, capName := range subexpNames {
						if capName == name && idx < len(submatches) {
							result.WriteString(submatches[idx])
							break
						}
					}
					i = j
				} else {
					result.WriteRune('$')
					i++
				}
			} else {
				result.WriteRune('$')
				i++
			}
		} else {
			result.WriteRune(runes[i])
			i++
		}
	}

	return result.String()
}

func processContent(content string, re *regexp.Regexp, replacement string, maxReplacements int) string {
	subexpNames := re.SubexpNames()

	var allMatches [][]int
	if maxReplacements == 0 {
		allMatches = re.FindAllStringSubmatchIndex(content, -1)
	} else {
		allMatches = re.FindAllStringSubmatchIndex(content, -1)
		if len(allMatches) > maxReplacements {
			allMatches = allMatches[:maxReplacements]
		}
	}

	if allMatches == nil {
		return content
	}

	var result strings.Builder
	lastEnd := 0

	for _, matchIdx := range allMatches {
		// matchIdx[0], matchIdx[1] = full match start/end
		start := matchIdx[0]
		end := matchIdx[1]

		result.WriteString(content[lastEnd:start])

		// Build submatches array
		numGroups := len(matchIdx) / 2
		submatches := make([]string, numGroups)
		for g := 0; g < numGroups; g++ {
			s := matchIdx[g*2]
			e := matchIdx[g*2+1]
			if s >= 0 && e >= 0 {
				submatches[g] = content[s:e]
			}
		}

		replaced := substituteCaptures(submatches, subexpNames, replacement)
		result.WriteString(replaced)
		lastEnd = end
	}

	result.WriteString(content[lastEnd:])
	return result.String()
}

type Config struct {
	find            string
	replaceWith     string
	files           []string
	preview         bool
	fixedStrings    bool
	maxReplacements int
	flags           string
}

func usageError(msg string) {
	fmt.Fprintf(os.Stderr, "error: %s\n\n", msg)
	fmt.Fprintf(os.Stderr, "Usage: sd [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\n")
	fmt.Fprintf(os.Stderr, "For more information try '--help'\n")
	os.Exit(2)
}

func parseArgs(args []string) (*Config, error) {
	cfg := &Config{}
	positional := []string{}
	endOfFlags := false
	flagsSetCount := 0

	i := 0
	for i < len(args) {
		arg := args[i]

		if endOfFlags {
			positional = append(positional, arg)
			i++
			continue
		}

		if arg == "--" {
			endOfFlags = true
			i++
			continue
		}

		if strings.HasPrefix(arg, "-") && arg != "-" {
			switch {
			case arg == "-p" || arg == "--preview":
				cfg.preview = true
				i++
			case arg == "-F" || arg == "--fixed-strings":
				cfg.fixedStrings = true
				i++
			case arg == "-h" || arg == "--help":
				printHelp()
				os.Exit(0)
			case arg == "-V" || arg == "--version":
				fmt.Printf("sd %s\n", version)
				os.Exit(0)
			case arg == "-n" || arg == "--max-replacements":
				if i+1 >= len(args) {
					return nil, fmt.Errorf("missing argument for %s", arg)
				}
				n, err := strconv.Atoi(args[i+1])
				if err != nil {
					return nil, fmt.Errorf("invalid number: %s", args[i+1])
				}
				cfg.maxReplacements = n
				i += 2
			case strings.HasPrefix(arg, "--max-replacements="):
				val := arg[len("--max-replacements="):]
				n, err := strconv.Atoi(val)
				if err != nil {
					return nil, fmt.Errorf("invalid number: %s", val)
				}
				cfg.maxReplacements = n
				i++
			case arg == "-f" || arg == "--flags":
				if flagsSetCount > 0 {
					return nil, fmt.Errorf("the argument '--flags <FLAGS>' cannot be used multiple times")
				}
				if i+1 >= len(args) {
					return nil, fmt.Errorf("missing argument for %s", arg)
				}
				cfg.flags = args[i+1]
				flagsSetCount++
				i += 2
			case strings.HasPrefix(arg, "--flags="):
				if flagsSetCount > 0 {
					return nil, fmt.Errorf("the argument '--flags <FLAGS>' cannot be used multiple times")
				}
				cfg.flags = arg[len("--flags="):]
				flagsSetCount++
				i++
			case strings.HasPrefix(arg, "-n") && len(arg) > 2:
				n, err := strconv.Atoi(arg[2:])
				if err != nil {
					return nil, fmt.Errorf("Found argument '%s' which wasn't expected, or isn't valid in this context", arg)
				}
				cfg.maxReplacements = n
				i++
			case strings.HasPrefix(arg, "-f") && len(arg) > 2:
				if flagsSetCount > 0 {
					return nil, fmt.Errorf("the argument '--flags <FLAGS>' cannot be used multiple times")
				}
				cfg.flags = arg[2:]
				flagsSetCount++
				i++
			default:
				return nil, fmt.Errorf("Found argument '%s' which wasn't expected, or isn't valid in this context", arg)
			}
		} else {
			positional = append(positional, arg)
			i++
		}
	}

	if len(positional) < 2 {
		return nil, fmt.Errorf("missing required arguments")
	}

	cfg.find = positional[0]
	cfg.replaceWith = positional[1]
	if len(positional) > 2 {
		cfg.files = positional[2:]
	}

	return cfg, nil
}

