	positional := []string{}
	endOfFlags := false
	flagsSetCount := 0

	i := 0
	for i < len(args) {
		arg := args[i]

		if endOfFlags {
			positional = append(positional, arg)
			i++
			continue
		}

		if arg == "--" {
			endOfFlags = true
			i++
			continue
		}

		if strings.HasPrefix(arg, "-") && arg != "-" {
			switch {
			case arg == "-p" || arg == "--preview":
				cfg.preview = true
				i++
			case arg == "-F" || arg == "--fixed-strings":
				cfg.fixedStrings = true
				i++
			case arg == "-h":
				printShortHelp()
				os.Exit(0)
			case arg == "--help":
				printLongHelp()
				os.Exit(0)
			case arg == "-V" || arg == "--version":
				fmt.Printf("sd %s\n", version)
				os.Exit(0)
			case arg == "-n" || arg == "--max-replacements":
				if i+1 >= len(args) {
					return nil, fmt.Errorf("a value is required for '--max-replacements <LIMIT>' but none was supplied")
				}
				n, err := strconv.Atoi(args[i+1])
				if err != nil {
					return nil, fmt.Errorf("invalid value '%s' for '--max-replacements <LIMIT>': invalid digit found in string", args[i+1])
				}
				cfg.maxReplacements = n
				i += 2
			case strings.HasPrefix(arg, "--max-replacements="):
				val := arg[len("--max-replacements="):]
				n, err := strconv.Atoi(val)
				if err != nil {
					return nil, fmt.Errorf("invalid value '%s' for '--max-replacements <LIMIT>': invalid digit found in string", val)
				}
				cfg.maxReplacements = n
				i++
			case arg == "-f" || arg == "--flags":
				if flagsSetCount > 0 {
					return nil, fmt.Errorf("the argument '--flags <FLAGS>' cannot be used multiple times")
				}
				if i+1 >= len(args) {
					return nil, fmt.Errorf("a value is required for '--flags <FLAGS>' but none was supplied")
				}
				cfg.flags = args[i+1]
				flagsSetCount++
				i += 2
			case strings.HasPrefix(arg, "--flags="):
				if flagsSetCount > 0 {
					return nil, fmt.Errorf("the argument '--flags <FLAGS>' cannot be used multiple times")
				}
				cfg.flags = arg[len("--flags="):]
				flagsSetCount++
				i++
			case strings.HasPrefix(arg, "-n") && len(arg) > 2:
				val := arg[2:]
				n, err := strconv.Atoi(val)
				if err != nil {
					// It's an unknown flag
					return nil, fmt.Errorf("unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'", arg, arg, arg)
				}
				cfg.maxReplacements = n
				i++
			case strings.HasPrefix(arg, "-f") && len(arg) > 2:
				if flagsSetCount > 0 {
					return nil, fmt.Errorf("the argument '--flags <FLAGS>' cannot be used multiple times")
				}
				cfg.flags = arg[2:]
				flagsSetCount++
				i++
			default:
				return nil, fmt.Errorf("unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'", arg, arg, arg)
			}
		} else {
			positional = append(positional, arg)
			i++
		}
	}

	if len(positional) < 1 {
		// Missing both FIND and REPLACE_WITH
		fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n")
		fmt.Fprintf(os.Stderr, "  <FIND>\n")
		fmt.Fprintf(os.Stderr, "  <REPLACE_WITH>\n")
		fmt.Fprintf(os.Stderr, "\n")
		fmt.Fprintf(os.Stderr, "Usage: %s <FIND> <REPLACE_WITH> [FILES]...\n\n", getProgName())
		fmt.Fprintf(os.Stderr, "For more information, try '--help'.\n")
		os.Exit(2)
	}

	if len(positional) < 2 {
		// Missing REPLACE_WITH
		fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n")
		fmt.Fprintf(os.Stderr, "  <REPLACE_WITH>\n")
		fmt.Fprintf(os.Stderr, "\n")
		fmt.Fprintf(os.Stderr, "Usage: %s <FIND> <REPLACE_WITH> [FILES]...\n\n", getProgName())
		fmt.Fprintf(os.Stderr, "For more information, try '--help'.\n")
		os.Exit(2)
	}

	cfg.find = positional[0]
	cfg.replaceWith = positional[1]
	if len(positional) > 2 {
		cfg.files = positional[2:]
	}

	return cfg, nil
}

func writeFilePreservePerms(path string, data []byte) error {
	// Get existing file permissions
	info, err := os.Stat(path)
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, info.Mode())
}

func main() {
	args := os.Args[1:]

	cfg, err := parseArgs(args)
	if err != nil {
		usageError(err.Error())
	}

	re, err := buildRegex(cfg.find, cfg.fixedStrings, cfg.flags)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err.Error())
		os.Exit(1)
	}

	if len(cfg.files) == 0 {
		// Read from stdin
		input, err := io.ReadAll(os.Stdin)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error reading stdin: %v\n", err)
			os.Exit(1)
		}
		output := processContent(string(input), re, cfg.replaceWith, cfg.maxReplacements)
		os.Stdout.WriteString(output)
	} else if cfg.preview {
		if len(cfg.files) == 1 {
			content, err := os.ReadFile(cfg.files[0])
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: %v\n", err)
				os.Exit(1)
			}
			output := processContent(string(content), re, cfg.replaceWith, cfg.maxReplacements)
			os.Stdout.WriteString(output)
		} else {
			for _, f := range cfg.files {
				content, err := os.ReadFile(f)
				if err != nil {
					fmt.Fprintf(os.Stderr, "error: %v\n", err)
					os.Exit(1)
				}
				output := processContent(string(content), re, cfg.replaceWith, cfg.maxReplacements)
				fmt.Printf("----- FILE %s -----\n", f)
				os.Stdout.WriteString(output)
			}
		}
	} else {
		for _, f := range cfg.files {
			content, err := os.ReadFile(f)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: %v\n", err)
				os.Exit(1)
			}
			output := processContent(string(content), re, cfg.replaceWith, cfg.maxReplacements)
			err = writeFilePreservePerms(f, []byte(output))
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: %v\n", err)
				os.Exit(1)
			}
		}
	}
}
