func buildRegex(find string, fixedStrings bool, flags string) (*regexp.Regexp, error) {
	pattern := find
	if fixedStrings {
		pattern = regexp.QuoteMeta(find)
	}

	useWordBoundary := strings.Contains(flags, "w")
	if useWordBoundary {
		pattern = `\b` + pattern + `\b`
	}

	multiLine := true
	caseInsensitive := false
	dotMatchesNewline := false

	for _, ch := range flags {
		switch ch {
		case 'i':
			caseInsensitive = true
		case 'c':
			caseInsensitive = false
		case 'm':
			multiLine = true
		case 'e':
			multiLine = false
		case 's':
			dotMatchesNewline = true
		}
	}

	var flagParts []byte
	if multiLine {
		flagParts = append(flagParts, 'm')
	}
	if caseInsensitive {
		flagParts = append(flagParts, 'i')
	}
	if dotMatchesNewline {
		flagParts = append(flagParts, 's')
	}

	var fullPattern string
	if len(flagParts) > 0 {
		fullPattern = "(?" + string(flagParts) + ")" + pattern
	} else {
		fullPattern = pattern
	}

	re, err := regexp.Compile(fullPattern)
	if err != nil {
		return nil, fmt.Errorf("invalid regex %s", err.Error())
	}
	return re, nil
}

func substituteCaptures(submatches []string, subexpNames []string, replacement string) string {
	var result strings.Builder
	runes := []rune(replacement)
	i := 0

	for i < len(runes) {
		if runes[i] == '$' {
			if i+1 < len(runes) {
				if runes[i+1] == '$' {
					result.WriteRune('$')
					i += 2
				} else if runes[i+1] == '{' {
					// ${name} or ${N}
					rest := string(runes[i+2:])
					end := strings.Index(rest, "}")
					if end >= 0 {
						name := rest[:end]
						i += 2 + end + 1

						// Try numeric
						if n, err := strconv.Atoi(name); err == nil {
							if n < len(submatches) {
								result.WriteString(submatches[n])
							}
						} else {
							// Named capture
							for idx, capName := range subexpNames {
								if capName == name && idx < len(submatches) {
									result.WriteString(submatches[idx])
									break
								}
							}
						}
					} else {
						result.WriteRune('$')
						i++
					}
				} else if unicode.IsDigit(runes[i+1]) {
					// $N or $NN...
					j := i + 1
					for j < len(runes) && unicode.IsDigit(runes[j]) {
						j++
					}
					numStr := string(runes[i+1 : j])
					n, _ := strconv.Atoi(numStr)
					if n < len(submatches) {
						result.WriteString(submatches[n])
					}
					i = j
				} else if unicode.IsLetter(runes[i+1]) || runes[i+1] == '_' {
					// $name
					j := i + 1
					for j < len(runes) && (unicode.IsLetter(runes[j]) || unicode.IsDigit(runes[j]) || runes[j] == '_') {
						j++
					}
					name := string(runes[i+1 : j])
					for idx, capName := range subexpNames {
						if capName == name && idx < len(submatches) {
							result.WriteString(submatches[idx])
							break
						}
					}
					i = j
				} else {
					result.WriteRune('$')
					i++
				}
			} else {
				result.WriteRune('$')
				i++
			}
		} else {
			result.WriteRune(runes[i])
			i++
		}
	}

	return result.String()
}

func processContent(content string, re *regexp.Regexp, replacement string, maxReplacements int) string {
	subexpNames := re.SubexpNames()

	allMatches := re.FindAllStringSubmatchIndex(content, -1)

	if allMatches == nil {
		return content
	}

	if maxReplacements > 0 && len(allMatches) > maxReplacements {
		allMatches = allMatches[:maxReplacements]
	}

	var result strings.Builder
	lastEnd := 0

	for _, matchIdx := range allMatches {
		start := matchIdx[0]
		end := matchIdx[1]

		result.WriteString(content[lastEnd:start])

		numGroups := len(matchIdx) / 2
		submatches := make([]string, numGroups)
		for g := 0; g < numGroups; g++ {
			s := matchIdx[g*2]
			e := matchIdx[g*2+1]
			if s >= 0 && e >= 0 {
				submatches[g] = content[s:e]
			}
		}

		replaced := substituteCaptures(submatches, subexpNames, replacement)
		result.WriteString(replaced)
		lastEnd = end
	}

	result.WriteString(content[lastEnd:])
	return result.String()
}

func getProgName() string {
	if len(os.Args) > 0 {
		name := os.Args[0]
		// Get basename
		for i := len(name) - 1; i >= 0; i-- {
			if name[i] == '/' || name[i] == '\\' {
				name = name[i+1:]
				break
			}
		}
		return name
	}
	return "sd"
}

// wrapText wraps text at maxWidth with given indent for continuation lines
func wrapText(text string, firstLineLen int, maxWidth int, indent string) string {
	words := strings.Fields(text)
	if len(words) == 0 {
		return ""
	}

	var lines []string
	currentLine := ""
	currentLen := firstLineLen

	for _, word := range words {
		if currentLine == "" {
			currentLine = word
			currentLen += len(word)
		} else if currentLen+1+len(word) <= maxWidth {
			currentLine += " " + word
			currentLen += 1 + len(word)
		} else {
			lines = append(lines, currentLine)
			currentLine = word
			currentLen = len(indent) + len(word)
		}
	}
	if currentLine != "" {
		lines = append(lines, currentLine)
	}

	return strings.Join(lines, "\n"+indent)
}

