	replaceWith     string
	files           []string
	preview         bool
	fixedStrings    bool
	maxReplacements int
	flags           string
}

func usageErrorFmt(msg string, fmtStr string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "error: %s\n\n", msg)
	fmt.Fprintf(os.Stderr, fmtStr, args...)
	fmt.Fprintf(os.Stderr, "\nFor more information, try '--help'.\n")
	os.Exit(2)
}

func usageError(msg string) {
	fmt.Fprintf(os.Stderr, "error: %s\n\n", msg)
	fmt.Fprintf(os.Stderr, "Usage: %s [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\n", getProgName())
	fmt.Fprintf(os.Stderr, "For more information, try '--help'.\n")
	os.Exit(2)
}

func parseArgs(args []string) (*Config, error) {
	cfg := &Config{}
	positional := []string{}
	endOfFlags := false
	flagsSetCount := 0
	flagsArg := ""

	i := 0
	for i < len(args) {
		arg := args[i]

		if endOfFlags {
			positional = append(positional, arg)
			i++
			continue
		}

		if arg == "--" {
			endOfFlags = true
			i++
			continue
		}

		if strings.HasPrefix(arg, "-") && arg != "-" {
			switch {
			case arg == "-p" || arg == "--preview":
				cfg.preview = true
				i++
			case arg == "-F" || arg == "--fixed-strings":
				cfg.fixedStrings = true
				i++
			case arg == "-h":
				printShortHelp()
				os.Exit(0)
			case arg == "--help":
				printLongHelp()
				os.Exit(0)
			case arg == "-V" || arg == "--version":
				fmt.Printf("sd %s\n", version)
				os.Exit(0)
			case arg == "-n" || arg == "--max-replacements":
				if i+1 >= len(args) {
					fmt.Fprintf(os.Stderr, "error: a value is required for '--max-replacements <LIMIT>' but none was supplied\n\n")
					fmt.Fprintf(os.Stderr, "For more information, try '--help'.\n")
					os.Exit(2)
				}
				n, err := strconv.Atoi(args[i+1])
				if err != nil {
					fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--max-replacements <LIMIT>': invalid digit found in string\n\n", args[i+1])
					fmt.Fprintf(os.Stderr, "For more information, try '--help'.\n")
					os.Exit(2)
				}
				cfg.maxReplacements = n
				i += 2
			case strings.HasPrefix(arg, "--max-replacements="):
				val := arg[len("--max-replacements="):]
				n, err := strconv.Atoi(val)
				if err != nil {
					fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--max-replacements <LIMIT>': invalid digit found in string\n\n", val)
					fmt.Fprintf(os.Stderr, "For more information, try '--help'.\n")
					os.Exit(2)
				}
				cfg.maxReplacements = n
				i++
			case arg == "-f" || arg == "--flags":
				if flagsSetCount > 0 {
					fmt.Fprintf(os.Stderr, "error: the argument '--flags <FLAGS>' cannot be used multiple times\n\n")
					fmt.Fprintf(os.Stderr, "Usage: %s [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\n", getProgName())
					fmt.Fprintf(os.Stderr, "For more information, try '--help'.\n")
					os.Exit(2)
				}
				if i+1 >= len(args) {
					fmt.Fprintf(os.Stderr, "error: a value is required for '--flags <FLAGS>' but none was supplied\n\n")
					fmt.Fprintf(os.Stderr, "For more information, try '--help'.\n")
					os.Exit(2)
				}
				cfg.flags = args[i+1]
				flagsArg = arg
				flagsSetCount++
				i += 2
			case strings.HasPrefix(arg, "--flags="):
				if flagsSetCount > 0 {
					fmt.Fprintf(os.Stderr, "error: the argument '--flags <FLAGS>' cannot be used multiple times\n\n")
					fmt.Fprintf(os.Stderr, "Usage: %s [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\n", getProgName())
					fmt.Fprintf(os.Stderr, "For more information, try '--help'.\n")
					os.Exit(2)
				}
				cfg.flags = arg[len("--flags="):]
				flagsArg = "--flags"
				flagsSetCount++
				i++
			case strings.HasPrefix(arg, "-n") && len(arg) > 2:
				val := arg[2:]
				n, err := strconv.Atoi(val)
				if err != nil {
					fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\n", arg, arg, arg)
					fmt.Fprintf(os.Stderr, "Usage: %s [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\n", getProgName())
					fmt.Fprintf(os.Stderr, "For more information, try '--help'.\n")
					os.Exit(2)
				}
				cfg.maxReplacements = n
				i++
			case strings.HasPrefix(arg, "-f") && len(arg) > 2:
				if flagsSetCount > 0 {
					fmt.Fprintf(os.Stderr, "error: the argument '--flags <FLAGS>' cannot be used multiple times\n\n")
					fmt.Fprintf(os.Stderr, "Usage: %s [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\n", getProgName())
					fmt.Fprintf(os.Stderr, "For more information, try '--help'.\n")
					os.Exit(2)
				}
				cfg.flags = arg[2:]
				flagsArg = "-f"
				flagsSetCount++
				i++
			default:
				fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\n", arg, arg, arg)
				fmt.Fprintf(os.Stderr, "Usage: %s [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\n", getProgName())
				fmt.Fprintf(os.Stderr, "For more information, try '--help'.\n")
				os.Exit(2)
			}
		} else {
			positional = append(positional, arg)
			i++
		}
	}
	_ = flagsArg

	if len(positional) < 1 {
		fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n")
		fmt.Fprintf(os.Stderr, "  <FIND>\n")
		fmt.Fprintf(os.Stderr, "  <REPLACE_WITH>\n")
		fmt.Fprintf(os.Stderr, "\n")
		fmt.Fprintf(os.Stderr, "Usage: %s <FIND> <REPLACE_WITH> [FILES]...\n\n", getProgName())
		fmt.Fprintf(os.Stderr, "For more information, try '--help'.\n")
		os.Exit(2)
	}

	if len(positional) < 2 {
		fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n")
		fmt.Fprintf(os.Stderr, "  <REPLACE_WITH>\n")
		fmt.Fprintf(os.Stderr, "\n")
		fmt.Fprintf(os.Stderr, "Usage: %s <FIND> <REPLACE_WITH> [FILES]...\n\n", getProgName())
		fmt.Fprintf(os.Stderr, "For more information, try '--help'.\n")
		os.Exit(2)
	}

	cfg.find = positional[0]
	cfg.replaceWith = positional[1]
	if len(positional) > 2 {
		cfg.files = positional[2:]
	}

	return cfg, nil
}

func writeFilePreservePerms(path string, data []byte) error {
	info, err := os.Stat(path)
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, info.Mode())
}

func main() {
	args := os.Args[1:]

	cfg, _ := parseArgs(args)

	re, err := buildRegex(cfg.find, cfg.fixedStrings, cfg.flags)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err.Error())
		os.Exit(1)
	}

	if len(cfg.files) == 0 {
		input, err := io.ReadAll(os.Stdin)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error reading stdin: %v\n", err)
			os.Exit(1)
		}
		output := processContent(string(input), re, cfg.replaceWith, cfg.maxReplacements)
		os.Stdout.WriteString(output)
	} else if cfg.preview {
		if len(cfg.files) == 1 {
			content, err := os.ReadFile(cfg.files[0])
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: %v\n", err)
				os.Exit(1)
			}
			output := processContent(string(content), re, cfg.replaceWith, cfg.maxReplacements)
			os.Stdout.WriteString(output)
		} else {
			for _, f := range cfg.files {
				content, err := os.ReadFile(f)
				if err != nil {
					fmt.Fprintf(os.Stderr, "error: %v\n", err)
					os.Exit(1)
				}
				output := processContent(string(content), re, cfg.replaceWith, cfg.maxReplacements)
				fmt.Printf("----- FILE %s -----\n", f)
				os.Stdout.WriteString(output)
			}
		}
	} else {
		for _, f := range cfg.files {
			content, err := os.ReadFile(f)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: %v\n", err)
				os.Exit(1)
			}
			output := processContent(string(content), re, cfg.replaceWith, cfg.maxReplacements)
			err = writeFilePreservePerms(f, []byte(output))
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: %v\n", err)
				os.Exit(1)
			}
		}
	}
}
