func printShortHelpRow(key, desc string, keyColWidth int, maxWidth int) {
	indent := strings.Repeat(" ", keyColWidth)
	fullKey := fmt.Sprintf("  %-*s", keyColWidth-2, key)

	// Check if key is too long
	if len(fullKey) > keyColWidth {
		// Key is longer than column, print key on its own line
		fmt.Println(fullKey)
		// Print description with proper indent
		remaining := maxWidth - keyColWidth
		wrapped := wrapText(desc, keyColWidth, maxWidth, indent)
		fmt.Println(indent + wrapped)
		return
	}

	// Normal case: key fits in column
	line := fullKey + desc
	if len(line) <= maxWidth {
		fmt.Println(line)
		return
	}

	// Need to wrap
	firstLineSpace := maxWidth - keyColWidth
	words := strings.Fields(desc)
	currentLine := ""
	firstLine := true
	for _, word := range words {
		if currentLine == "" {
			currentLine = word
		} else {
			limit := maxWidth - keyColWidth
			if firstLine {
				limit = firstLineSpace
			}
			if len(currentLine)+1+len(word) <= limit {
				currentLine += " " + word
			} else {
				if firstLine {
					fmt.Println(fullKey + currentLine)
					firstLine = false
				} else {
					fmt.Println(indent + currentLine)
				}
				currentLine = word
			}
		}
	}
	if currentLine != "" {
		if firstLine {
			fmt.Println(fullKey + currentLine)
		} else {
			fmt.Println(indent + currentLine)
		}
	}
}

