with open('/workspace/sd_go/main.go', 'r') as f:
    content = f.read()

old = '''func writeFilePreservePerms(path string, data []byte) error {
	info, err := os.Stat(path)
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, info.Mode())
}'''

new = '''func writeFilePreservePerms(path string, data []byte) error {
	// Get original file info
	info, err := os.Stat(path)
	if err != nil {
		return err
	}
	mode := info.Mode()

	// Write to a temp file in the same directory, then rename
	// This allows writing to read-only files (since we own the parent dir)
	dir := filepath.Dir(path)
	base := filepath.Base(path)

	tmpFile, err := os.CreateTemp(dir, "."+base+".tmp*")
	if err != nil {
		// Fallback to direct write
		return os.WriteFile(path, data, mode)
	}
	tmpPath := tmpFile.Name()

	// Write data to temp file
	_, err = tmpFile.Write(data)
	tmpFile.Close()
	if err != nil {
		os.Remove(tmpPath)
		return err
	}

	// Set the permissions on the temp file
	if err := os.Chmod(tmpPath, mode); err != nil {
		os.Remove(tmpPath)
		return err
	}

	// Rename temp file to original
	if err := os.Rename(tmpPath, path); err != nil {
		os.Remove(tmpPath)
		return err
	}

	return nil
}'''

content = content.replace(old, new)
with open('/workspace/sd_go/main.go', 'w') as f:
    f.write(content)
print("Done")
EOF
